import * as m from './scripts/text/slug.ts';

const cases = [['  Hello, World! 2026 ', 'hello-world-2026'], ['', ''], ['!!!', ''], ['A--B__c', 'a-b-c'], ['-x-', 'x']];
for (const [input, want] of cases) { const got = m.slugify(input); if (got !== want) { console.error(JSON.stringify({ input, got, want })); process.exit(1); } }
